#!/usr/bin/env node
const urls = [
  'https://agenskill.onrender.com/health',
  'https://agenskill-api.onrender.com/health'
];

(async () => {
  for (const url of urls) {
    try {
      const res = await fetch(url);
      let body = '';
      try { body = JSON.stringify(await res.json()); } catch { body = '(non-json body)'; }
      console.log(`${url} -> HTTP ${res.status} ${body}`);
    } catch (err) {
      console.log(`${url} -> FAILED: ${err.message} | cause: ${err.cause ? (err.cause.message || err.cause.code) : 'n/a'}`);
    }
  }
})();

#!/usr/bin/env node
const url = process.argv[2] || 'https://agenskill-api.onrender.com/health';
const attempts = 5;

const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  for (let i = 1; i <= attempts; i++) {
    try {
      const res = await fetch(url);
      let body = '';
      try { body = JSON.stringify(await res.json()); } catch { body = '(non-json body)'; }
      console.log(`attempt ${i}: ${url} -> HTTP ${res.status} ${body}`);
      return;
    } catch (err) {
      console.log(`attempt ${i}: FAILED: ${err.message} | cause: ${err.cause ? (err.cause.message || err.cause.code) : 'n/a'}`);
      if (i < attempts) await sleep(2000);
    }
  }
  process.exit(1);
})();

